Here is the commit message:
Fix broken iio_device_get_sample_size with same-index
 channels

This fixes a bug introduced in 4792fa3.

Signed-off-by: Paul Cercueil <paul.cercueil@analog.com>

Here is the root cause:
The bug was caused by the failure to properly track the previous channel in the loop that calculates the sample size, which led to incorrect calculations when handling channels with the same index. This oversight resulted in the function not correctly aggregating the sample sizes for these channels.

Here is the patch:

 ssize_t iio_device_get_sample_size_mask(const struct iio_device *dev,
 		const uint32_t *mask, size_t words)
 {
 	ssize_t size = 0;
 	unsigned int i;
 	const struct iio_channel *prev = NULL;

 	if (words != (dev->nb_channels + 31) / 32)
 		return -EINVAL;

 	for (i = 0; i < dev->nb_channels; i++) {
 		const struct iio_channel *chn = dev->channels[i];
 		unsigned int length = chn->format.length / 8 *
 			chn->format.repeat;

 		if (chn->index < 0)
 			break;
 		if (!TEST_BIT(mask, chn->number))
 			continue;

 		if (prev && chn->index == prev->index) {
 			prev = chn;
 			continue;
 		}

 		if (size % length)
 			size += 2 * length - (size % length);
 		else
 			size += length;
+
+		prev = chn;
 	}
 	return size;
 }



